// Initialize performance test configuration
const perfConfig = {
  testId: 'perf_' + Date.now(),
  startTime: new Date().toISOString(),
  testSuite: 'performance',
  loadTestConfig: {
    concurrentSessions: $json.concurrentSessions || 10,
    testDuration: $json.testDuration || 300,
    rampUpTime: $json.rampUpTime || 60,
    requestsPerSecond: $json.requestsPerSecond || 50
  },
  thresholds: {
    apiResponseTime: 2.0,
    aiDecisionLatency: 5.0,
    memoryRetrievalTime: 1.0,
    websocketLatency: 0.5,
    cpuUsage: 80,
    memoryUsage: 85,
    errorRate: 5
  },
  metrics: {
    responseTimes: [],
    throughput: [],
    errorCounts: {},
    systemResources: []
  }
};

$items[0].json.perfConfig = perfConfig;

return [{
  json: {
    ...perfConfig,
    status: 'initialized',
    currentTest: 'concurrent_sessions'
  }
}];

// Analyze performance test results and generate comprehensive report
const perfResults = {
  testId: $json.testId,
  testSuite: 'performance',
  startTime: $json.startTime,
  endTime: new Date().toISOString(),
  totalDuration: Date.now() - new Date($json.startTime).getTime(),
  tests: [
    {
      name: 'concurrent_sessions',
      status: $json.concurrentSessionResults ? 'passed' : 'failed',
      maxConcurrentSessions: $json.maxConcurrentSessions || 0,
      averageResponseTime: $json.concurrentSessionAvgTime || 0,
      errorRate: $json.concurrentSessionErrorRate || 0,
      throughput: $json.concurrentSessionThroughput || 0,
      details: $json.concurrentSessionDetails || {}
    },
    {
      name: 'ai_decision_latency',
      status: $json.aiDecisionResults ? 'passed' : 'failed',
      averageLatency: $json.aiDecisionAvgLatency || 0,
      p95Latency: $json.aiDecisionP95Latency || 0,
      p99Latency: $json.aiDecisionP99Latency || 0,
      throughput: $json.aiDecisionThroughput || 0,
      details: $json.aiDecisionDetails || {}
    },
    {
      name: 'memory_retrieval',
      status: $json.memoryRetrievalResults ? 'passed' : 'failed',
      averageRetrievalTime: $json.memoryAvgRetrievalTime || 0,
      cacheHitRate: $json.memoryCacheHitRate || 0,
      queryComplexityImpact: $json.memoryComplexityImpact || {},
      databaseSizeImpact: $json.memoryDatabaseSizeImpact || {},
      details: $json.memoryRetrievalDetails || {}
    },
    {
      name: 'database_optimization',
      status: $json.databaseOptimizationResults ? 'passed' : 'failed',
      averageQueryTime: $json.databaseAvgQueryTime || 0,
      indexEffectiveness: $json.databaseIndexEffectiveness || {},
      queryPlanOptimizations: $json.databaseQueryOptimizations || [],
      scalability: $json.databaseScalability || {},
      details: $json.databaseOptimizationDetails || {}
    },
    {
      name: 'websocket_stress',
      status: $json.websocketStressResults ? 'passed' : 'failed',
      maxConnections: $json.websocketMaxConnections || 0,
      averageLatency: $json.websocketAvgLatency || 0,
      messageThroughput: $json.websocketMessageThroughput || 0,
      connectionDropRate: $json.websocketConnectionDropRate || 0,
      details: $json.websocketStressDetails || {}
    },
    {
      name: 'voice_chat_load',
      status: $json.voiceChatResults ? 'passed' : 'failed',
      maxConcurrentSessions: $json.voiceMaxConcurrentSessions || 0,
      averageLatency: $json.voiceAvgLatency || 0,
      audioQualityMetrics: $json.voiceAudioQualityMetrics || {},
      resourceUtilization: $json.voiceResourceUtilization || {},
      details: $json.voiceChatDetails || {}
    },
    {
      name: 'throughput_capacity',
      status: $json.throughputResults ? 'passed' : 'failed',
      maxRPS: $json.throughputMaxRPS || 0,
      sustainedRPS: $json.throughputSustainedRPS || 0,
      averageResponseTime: $json.throughputAvgResponseTime || 0,
      errorRate: $json.throughputErrorRate || 0,
      details: $json.throughputDetails || {}
    }
  ],
  systemResources: $json.systemResources || [],
  thresholds: $json.thresholds || {}
};

// Calculate performance summary
const passedTests = perfResults.tests.filter(t => t.status === 'passed').length;
const totalTests = perfResults.tests.length;
const successRate = (passedTests / totalTests * 100).toFixed(1);

// Performance metrics summary
const performanceSummary = {
  averageResponseTime: perfResults.tests.reduce((sum, t) => sum + (t.averageResponseTime || t.averageLatency || 0), 0) / totalTests,
  maxThroughput: Math.max(...perfResults.tests.map(t => t.throughput || 0)),
  averageErrorRate: perfResults.tests.reduce((sum, t) => sum + (t.errorRate || 0), 0) / totalTests,
  peakResourceUsage: {
    cpu: Math.max(...(perfResults.systemResources.map(r => r.cpu) || [0])),
    memory: Math.max(...(perfResults.systemResources.map(r => r.memory) || [0]))
  }
};

// Determine overall performance rating
let performanceRating = 'excellent';
if (performanceSummary.averageResponseTime > perfResults.thresholds.apiResponseTime * 2) {
  performanceRating = 'poor';
} else if (performanceSummary.averageResponseTime > perfResults.thresholds.apiResponseTime) {
  performanceRating = 'fair';
} else if (performanceSummary.averageResponseTime > perfResults.thresholds.apiResponseTime * 0.5) {
  performanceRating = 'good';
}

if (performanceSummary.averageErrorRate > perfResults.thresholds.errorRate) {
  performanceRating = Math.min(performanceRating, 'poor');
}

const summary = {
  totalTests,
  passedTests,
  failedTests: totalTests - passedTests,
  successRate: parseFloat(successRate),
  overallStatus: successRate >= 90 ? 'passed' : successRate >= 70 ? 'warning' : 'failed',
  performanceRating,
  ...performanceSummary
};

return [{
  json: {
    testSuite: 'performance',
    ...perfResults,
    summary,
    performanceSummary,
    status: summary.overallStatus,
    timestamp: new Date().toISOString()
  }
}];

// Generate performance recommendations based on test results
const recommendations = [];

if ($json.performanceSummary.averageResponseTime > $json.thresholds.apiResponseTime) {
  recommendations.push({
    category: 'response_time',
    priority: 'high',
    issue: 'Average response time exceeds threshold',
    suggestion: 'Consider implementing caching, optimizing database queries, or scaling resources'
  });
}

if ($json.performanceSummary.averageErrorRate > $json.thresholds.errorRate) {
  recommendations.push({
    category: 'error_rate',
    priority: 'critical',
    issue: 'Error rate exceeds acceptable threshold',
    suggestion: 'Investigate error patterns, implement better error handling, and improve system reliability'
  });
}

if ($json.performanceSummary.peakResourceUsage.cpu > $json.thresholds.cpuUsage) {
  recommendations.push({
    category: 'cpu_usage',
    priority: 'medium',
    issue: 'CPU usage consistently high during load',
    suggestion: 'Optimize CPU-intensive operations, consider horizontal scaling, or upgrade hardware'
  });
}

if ($json.performanceSummary.peakResourceUsage.memory > $json.thresholds.memoryUsage) {
  recommendations.push({
    category: 'memory_usage',
    priority: 'medium',
    issue: 'Memory usage approaches limit',
    suggestion: 'Implement memory optimization, reduce memory leaks, or increase available memory'
  });
}

// Check specific test results for recommendations
$json.tests.forEach(test => {
  if (test.name === 'ai_decision_latency' && test.averageLatency > $json.thresholds.aiDecisionLatency) {
    recommendations.push({
      category: 'ai_performance',
      priority: 'high',
      issue: 'AI decision latency is too high',
      suggestion: 'Optimize AI model inference, implement model caching, or use faster hardware'
    });
  }

  if (test.name === 'memory_retrieval' && test.averageRetrievalTime > $json.thresholds.memoryRetrievalTime) {
    recommendations.push({
      category: 'memory_performance',
      priority: 'medium',
      issue: 'Memory retrieval is slow',
      suggestion: 'Improve database indexing, implement better caching strategies, or optimize queries'
    });
  }

  if (test.name === 'websocket_stress' && test.connectionDropRate > 5) {
    recommendations.push({
      category: 'websocket_reliability',
      priority: 'high',
      issue: 'High WebSocket connection drop rate',
      suggestion: 'Implement connection pooling, improve error handling, and optimize network configuration'
    });
  }
});

return [{
  json: {
    testId: $json.testId,
    recommendations,
    summary: {
      totalRecommendations: recommendations.length,
      criticalIssues: recommendations.filter(r => r.priority === 'critical').length,
      highPriorityIssues: recommendations.filter(r => r.priority === 'high').length,
      mediumPriorityIssues: recommendations.filter(r => r.priority === 'medium').length
    },
    timestamp: new Date().toISOString()
  }
}];
